'use client'
import type { SelfMcpDecisionRequest, SelfMcpDecisionResult, SelfMcpProposal, SelfMcpReviewSnapshot } from '@rerun/contracts'

/**
 * Browser client for the self-MCP review API at
 * /api/desktop/agents/[agentId]/self-mcp. Every call POSTs a typed envelope
 * (`selfMcpRequestSchema`): list, review, decide (decision id generated by the
 * caller for idempotent retries) or dismiss. The client never carries
 * authority — the server re-checks the owner and the CAS revisions on every
 * request, and a stale/disposed panel stops issuing work.
 */
export type SelfMcpListResult = { proposals: SelfMcpProposal[] }

export function createDesktopSelfMcpClient(agentId: string) {
    const url = `/api/desktop/agents/${encodeURIComponent(agentId)}/self-mcp`
    const controllers = new Set<AbortController>()
    let closed = false
    async function request<T>(body: { action: string } & Record<string, unknown>): Promise<T> {
        if (closed) throw new Error('Self-MCP panel owner changed')
        const controller = new AbortController()
        controllers.add(controller)
        try {
            const signal = AbortSignal.any([controller.signal, AbortSignal.timeout(30_000)])
            const response = await fetch(url, { method: 'POST', cache: 'no-store', signal, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) })
            const data = await response.json()
            signal.throwIfAborted()
            if (closed) throw new Error('Self-MCP panel owner changed')
            if (!response.ok) throw new Error((data as { error?: string }).error ?? 'Self-MCP review request failed')
            return data as T
        } finally {
            controllers.delete(controller)
        }
    }
    const list = () => request<SelfMcpListResult>({ action: 'list' })
    const review = (proposalId: string) => request<SelfMcpReviewSnapshot>({ action: 'review', proposalId })
    const decide = (decision: SelfMcpDecisionRequest) => request<SelfMcpDecisionResult>({ action: 'decide', decision })
    const dismiss = (proposalId: string, expectedProposalRevision: number) => request<SelfMcpDecisionResult>({ action: 'dismiss', proposalId, expectedProposalRevision })
    return {
        list,
        review,
        decide,
        dismiss,
        dispose() {
            closed = true
            for (const controller of controllers) controller.abort()
            controllers.clear()
        },
    }
}
export type DesktopSelfMcpClient = ReturnType<typeof createDesktopSelfMcpClient>
